export default function (pi) {
  pi.on("tool_call", async (event, ctx) => {
    ctx.ui.notify("plain");
    ctx.ui.notify("one", "info");
    ctx.ui.notify("two", "warning");
    ctx.ui.notify("three", "error");
    return { block: true, reason: "notified" };
  });
}
